solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <optional>
#include <span>
#include <string_view>
#include <vector>

struct Index { std::vector<std::size_t> offsets; bool truncated; };

static std::uint32_t lengthAt(std::span<const std::uint8_t> f, std::size_t at)
{
    return f[at] | (f[at + 1] << 8) | (f[at + 2] << 16) | (static_cast<std::uint32_t>(f[at + 3]) << 24);
}

Index buildIndex(std::span<const std::uint8_t> file)
{
    Index index{ {}, false };
    std::size_t at{ 0 };
    while (at < file.size())
    {
        if (file.size() - at < 4) { index.truncated = true; break; }
        const std::uint32_t length{ lengthAt(file, at) };
        if (file.size() - at - 4 < length) { index.truncated = true; break; }
        index.offsets.push_back(at + 4);
        at += 4 + length;
    }
    return index;
}

std::span<const std::uint8_t> recordAt(std::span<const std::uint8_t> file, const Index& index, std::size_t i)
{
    if (i >= index.offsets.size()) return {};
    const std::size_t at{ index.offsets[i] };
    return file.subspan(at, lengthAt(file, at - 4));
}

std::optional<std::size_t> findRecord(std::span<const std::uint8_t> file, const Index& index, std::string_view text)
{
    for (std::size_t i{ 0 }; i < index.offsets.size(); ++i)
    {
        const auto r{ recordAt(file, index, i) };
        if (r.size() == text.size() && std::equal(r.begin(), r.end(), text.begin(), [](std::uint8_t a, char b) { return a == static_cast<std::uint8_t>(b); }))
            return i;
    }
    return std::nullopt;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
static void add(Bytes& f, std::string_view s) { const auto n{ static_cast<std::uint32_t>(s.size()) }; for (int i{ 0 }; i < 4; ++i) f.push_back(static_cast<std::uint8_t>(n >> (8 * i))); f.insert(f.end(), s.begin(), s.end()); }

TEST("indexing records") {
    Bytes f;
    add(f, "alpha"); add(f, ""); add(f, "gamma ray");
    const Index idx{ buildIndex(f) };
    CHECK(!idx.truncated);
    CHECK_EQ(idx.offsets, (std::vector<std::size_t>{ 4, 13, 17 }));
}
TEST("views point into the file") {
    Bytes f;
    add(f, "alpha"); add(f, "beta");
    const Index idx{ buildIndex(f) };
    const auto r{ recordAt(f, idx, 1) };
    CHECK_EQ(r.size(), 4u);
    CHECK(r.data() == f.data() + 13);
    CHECK(recordAt(f, idx, 2).empty());
}
TEST("searching") {
    Bytes f;
    add(f, "alpha"); add(f, "beta"); add(f, "beta");
    const Index idx{ buildIndex(f) };
    CHECK_EQ(findRecord(f, idx, "beta").value_or(99), 1u);
    CHECK(!findRecord(f, idx, "bet").has_value());
}
TEST("truncated files") {
    Bytes f;
    add(f, "complete");
    add(f, "cut short");
    f.resize(f.size() - 3);
    const Index idx{ buildIndex(f) };
    CHECK(idx.truncated);
    CHECK_EQ(idx.offsets.size(), 1u);
    Bytes g;
    add(g, "x");
    g.push_back(1); g.push_back(0);
    CHECK(buildIndex(g).truncated);
    CHECK(!buildIndex(Bytes{}).truncated);
}

